    'RegisterSimpleRisk'=>'등록 SimpleRisk',
    'RegistrationText'=>'등록된 SimpleRisk 인스턴스에는 업그레이드 및 보안 제어 프레임워크(SCF) Extras에 대한 액세스 권한이 즉시 부여됩니다. Upgrade Extra는 버튼 클릭 한 번으로 SimpleRisk 인스턴스를 백업 및 업그레이드할 수 있는 기능을 제공합니다. SCF(Secure Controls Framework) Extra는 SimpleRisk 거버넌스 기능에 통합된 공통 제어 프레임워크를 제공합니다. SimpleRisk를 등록하면 등록 정보가 SimpleRisk에서 호스팅하는 서버로 전송됩니다. 제공된 등록 정보는 SimpleRisk에서 고객에게 새 릴리스 및 보안 업데이트를 알리는 데 사용됩니다. SimpleRisk를 등록하면 마케팅 커뮤니케이션에 참여하게 되지만 이러한 커뮤니케이션의 수신 거부 링크를 사용하여 언제든지 거부할 수 있습니다. SimpleRisk는 고객의 개인 정보를 존중하며 SimpleRisk 등록 프로세스를 통해 제공된 정보는 제3자에게 절대 판매되지 않습니다.',
