    'QuestionnaireDraftAuditLogViaApi' => '연락처 "{$contact_name}"에 대한 설문지 "{$questionnaire_name}"가 사용자 "{$user_name} "에 의해 API를 통해 초안으로 저장되었습니다.',
    // Bad-input response for the questionnaire risk-list endpoints, which
